ALTER TABLE bookings ADD CONSTRAINT staff_booking_deadlines CHECK(origin IS NULL OR state NOT IN('held','confirmed') OR(accepted_at IS NOT NULL AND(state<>'held' OR hold_deadline IS NOT NULL)));
CREATE OR REPLACE FUNCTION validate_accepted_booking() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE b public.bookings%ROWTYPE;BEGIN SELECT * INTO b FROM public.bookings WHERE id=NEW.id;IF b.origin='staff' AND b.state IN('held','confirmed') AND(NOT EXISTS(SELECT FROM public.invoices i WHERE i.booking_id=b.id AND i.organization_id=b.organization_id AND i.property_id=b.property_id AND i.customer_id=b.customer_id AND i.state='issued' AND i.pricing_snapshot=b.pricing_snapshot) OR NOT EXISTS(SELECT FROM public.room_allocations a WHERE a.booking_id=b.id AND a.state='active' AND a.kind=CASE WHEN b.state='held' THEN 'hold' ELSE 'stay' END AND a.starts_on=b.starts_on AND a.ends_on IS NOT DISTINCT FROM b.ends_on)) THEN RAISE EXCEPTION 'INVALID_STATE' USING ERRCODE='P0409';END IF;RETURN NULL;END $$;REVOKE ALL ON FUNCTION validate_accepted_booking() FROM PUBLIC;